snapshot(materials: KnowledgeMaterial[], articles: KnowledgeArticle[]) {
  if (this.closed) throw Error("Research session has ended");
  const identity = stableDigest({materials: materials.map(m=>[m.key,m.revisionId,m.digest]).sort(), articles: articles.map(a=>[a.document.key,a.revision]).sort()});
  if (this.fixed) {
    if (identity !== this.identity) throw Error("KNOWLEDGE_INPUT_CHANGED: research scope changed within workflow");
    return this.fixed;
  }
  this.root = mkdtempSync(join(tmpdir(), "omem-knowledge-session-"));
  const file = join(this.root, "snapshot.sqlite");
  const db = researchSnapshot({repository:this.repository,materials,articles,file,includeUnanchoredState:true});
  db.close();
  this.identity = identity;
  this.fixed = {identity:randomUUID(),file,materials:[...materials],articles:[...articles]};
  return this.fixed;

private async runRole(role: string, offers: Offer[], articles: KnowledgeArticle[], task: Record<string, unknown>, validate?: (out: unknown) => unknown): Promise<RunResult> {
  if (this.nativeResearch && !this.sessions.getStore()) return this.withSession(() => this.runRole(role, offers, articles, task, validate));
  if (this.stopping) throw Error("Knowledge pipeline stopped");
  this.assertOriginals(offers);
  const bundle = this.registry.load(role);
  const refs = [{ role, task, workflow: this.nativeResearch ? "native-research@1" : "bounded-context@1", retryTag: this.options.retryTag, materials: offers.map(o => ({ key: o.material.key, revisionId: o.material.revisionId, digest: o.material.digest, identityDigest: stableDigest({title:o.material.title,path:o.material.path,namespace:o.material.namespace,conversationId:o.material.conversationId,actorId:o.material.actorId,actorVerifiedBy:o.material.actorVerifiedBy,eventAt:o.material.eventAt,quoted:o.material.quoted,forwarded:o.material.forwarded}), ranges: o.ranges })),
    articles: articles.map(a => ({ key: a.document.key, revision: a.revision })), model: this.profile.model, effort: this.profile.effort, budget: this.options.budget, bundleHash: bundle.bundleHash }];
  const { job } = this.repository.store.jobs.enqueue({ kind: `knowledge:${role}`, inputRefs: refs, roleVersion: bundle.bundleHash, policyVersion: "knowledge@1", maxAttempts: 3, cause: "knowledge-generation" });
  const result = () => {
    this.assertOriginals(offers);
    const row = this.repository.store.db.prepare("SELECT output_json,trace_json,created_at FROM role_outputs WHERE job_id=? ORDER BY attempt DESC LIMIT 1").get(job.id) as { output_json: string; trace_json: string; created_at: string } | undefined;
    if (!row) throw Error("Completed knowledge job has no output");
    const out = JSON.parse(row.output_json); const normalized = validate?.(out); return { result: normalized ?? out, trace: JSON.parse(row.trace_json) as RoleRunTrace, at: row.created_at, jobId: job.id };
  };
  if (job.state === "succeeded") return result();
  if (["failed", "cancelled", "awaiting_user"].includes(job.state)) throw Error(`${role} requires retry: ${job.lastError ?? job.state} (job ${job.id})`);
  const worker = new DurableJobWorker(this.repository.store.jobs, `knowledge-${job.id}`, {
    [`knowledge:${role}`]: async (lease, signal) => {
      this.options.log?.(`AI ${role}: ${String(task.targetKeys ?? task.title ?? "catalog")}`);
      const run = await this.gateway.run({ roleId: role, profile: this.profile, profileBinding: { roleId: role, profileId: this.profile.id }, context: this.context(role, lease.id, offers, articles, task), signal, budget: this.options.budget, validateOutput: validate,
        ...(this.nativeResearch ? { research: (workspace, schema, validate) => {
          const rangeOnly = (task.reviewScope as {mode?:string}|undefined)?.mode === "citation_ranges";
          const drafts = (task.drafts ?? []) as KnowledgeDocument[];
          const ranges = rangeOnly ? drafts.flatMap(d=>[
            ...d.citations.flatMap(c=>c.target.kind==="material"?[{key:c.target.key,startLine:c.target.startLine!,endLine:c.target.endLine!}]:[]),
            ...d.sections.flatMap(s=>s.reviewSources ?? []),
          ]) : undefined;
          const keys = new Set(ranges?.map(r=>r.key));
          const articleKeys = new Set(drafts.flatMap(d=>d.citations.filter(c=>c.target.kind==="article").map(c=>c.target.key)));
          return prepareAgentResearch({ repository:this.repository,
            materials:offers.filter(o=>!rangeOnly || keys.has(o.material.key)).map(o=>o.material),
            articles:rangeOnly ? articles.filter(a=>articleKeys.has(a.document.key)) : articles,
            workspace, schema, validate, signal,
            snapshotFactory:()=>this.sessions.getStore()!.snapshot(offers.map(o=>o.material),articles),
            ...(rangeOnly ? {allowedTools:["read_material","read_fragments","read_section","read_image","read_knowledge","submit_result"],rangeEvidence:ranges} : {tools:followupStateTools(offers.map(o=>o.material))}),

const deadline = performance.now() + (this.rankingOptions.budgetMs ?? 20_000);
const pool = candidatePool(hits.map(h => ({ ...h, id: h.unit.id, owner: h.unit.owner })), hits.length);
const scored = new Map<string, number>();
let reason: "budget" | "failed" | undefined;
// Forty is a batch size, never a global admission cutoff. Small sub-batches
// let cancellation and elapsed-time budgets take effect without losing all work.
for (let offset = 0; offset < pool.length; offset += 8) {
  q.signal?.throwIfAborted();
  if (performance.now() >= deadline) { reason = "budget"; break; }
  const batch = pool.slice(offset, offset + 8);
  const passages = batch.flatMap(h => rerankPassages(h.unit.text, q.text, h.excerpt,
    h.unit.materialDescription?.description.concepts ?? [], h.matchedRanges)
    .flatMap(text => {
      const input = h.unit.context.slice(0, 160) + "\n" + text;
      return (model.windows?.(q.text, input) ?? [input]).map(input => ({ h, input }));
    }));
  try {
    const scores = await model.score(q.text, passages.map(p => p.input), { signal: q.signal, deadline });
    if (scores.length !== passages.length || scores.some(s => !Number.isFinite(s))) throw Error("Invalid reranker score batch");
    passages.forEach((p, i) => scored.set(p.h.unit.id, Math.max(scored.get(p.h.unit.id) ?? -Infinity, scores[i]!)));
    this.observe(observer, "reranker-input", passages.map((p, i) => ({ ...p.h, excerpt: p.input, score: scores[i]! })), model.id);
  } catch (error) {
    q.signal?.throwIfAborted();
    reason = String(error).includes("RERANK_BUDGET_EXHAUSTED") ? "budget" : "failed";
    this.rankingError = String(error);
    break;
  }
}
const max = Math.max(...hits.map(h => h.score), 1e-6);
hits = hits.map(h => {
  const score = scored.get(h.unit.id);
  return score === undefined
    ? { ...h, score: h.score / max * 0.3, rankingStatus: { state: "unscored" as const, reason: reason ?? "failed", model: model.id } }
    : { ...h, score: score * 0.7 + h.score / max * 0.3,
        rankingStatus: { state: "scored" as const, model: model.id },
        reranking: { model: model.id, relevance: score, retrievalScore: h.score }, routes: [...h.routes, "cross-encoder"] };
});
if (!reason) this.rankingError = null;
this.observe(observer, "reranker", hits, model.id, reason);

/** Optional cross-encoder score, separate from fusion and host preferences.
 * Relevance is an uncalibrated model output, not an answer probability. */
reranking?: {
  model: string;
  relevance: number;
  retrievalScore: number;
};
rankingStatus?: { state: "scored" | "unscored"; reason?: "budget" | "failed"; model: string };

score(query, passages, options = {}) {
  const work = serial.then(async () => {
    const result: number[] = [];
    for (let i = 0; i < passages.length; i += 4) {
      options.signal?.throwIfAborted();
      if (options.deadline !== undefined && performance.now() >= options.deadline)
        throw Error("RERANK_BUDGET_EXHAUSTED");
      const batch = passages.slice(i, i + 4);
      if (batch.some(text => tokenizer.encode(query, { text_pair: text }).length > 512))
        throw Error("Reranker paired input exceeds token budget");
      const encoded = tokenizer(
        batch.map(() => query),
        {
          text_pair: batch,
          padding: true,
          truncation: false,
          max_length: 512,
        },
      );
      const output = await model(encoded);
      const logits = output.logits.tolist() as number[][];
      for (const row of logits) {
        const logit = row[0];
        if (logit === undefined || !Number.isFinite(logit))
          throw Error("Invalid reranker score");
        result.push(1 / (1 + Math.exp(-logit / 3)));

